CREATE TABLE IF NOT EXISTS user_google_credentials (created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, user_uuid uuid PRIMARY KEY, google_subject VARCHAR(255) NOT NULL, access_token TEXT NOT NULL, refresh_token TEXT NULL, access_token_expires_at TIMESTAMP WITH TIME ZONE NOT NULL, granted_scopes TEXT NOT NULL, CONSTRAINT fk_user_google_credentials_user_uuid__user_uuid FOREIGN KEY (user_uuid) REFERENCES users(user_uuid) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE user_google_credentials ADD CONSTRAINT user_google_credentials_google_subject_unique UNIQUE (google_subject);
CREATE TABLE IF NOT EXISTS user_auth_refresh_tokens (created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, refresh_token_uuid uuid PRIMARY KEY, user_uuid uuid NOT NULL, token_hash VARCHAR(64) NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, revoked_at TIMESTAMP WITH TIME ZONE NULL, CONSTRAINT fk_user_auth_refresh_tokens_user_uuid__user_uuid FOREIGN KEY (user_uuid) REFERENCES users(user_uuid) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX user_auth_refresh_tokens_user_uuid ON user_auth_refresh_tokens (user_uuid);
ALTER TABLE user_auth_refresh_tokens ADD CONSTRAINT user_auth_refresh_tokens_token_hash_unique UNIQUE (token_hash);
